"""Original OPC/ACCDT package controls generated by Python's ZIP implementation.

These qualify package inspection, not Access-native template creation or rows.
No database code runs, no third-party fixture is copied, and input bytes are checked.
"""

import argparse
import csv
import io
from pathlib import Path
import subprocess
import tempfile
import zipfile


TYPES = '''<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">
<Default Extension="xml" ContentType="text/xml"/>
<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>
</Types>'''
ROOT = '''<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
<Relationship Id="r1" Type="http://schemas.microsoft.com/office/access/2005/04/template/start" Target="template/main.xml"/>
</Relationships>'''
RELS = '''<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
<Relationship Id="r1" Type="urn:tablecraft:original-inert-test" Target="../tables/contacts.xml"/>
</Relationships>'''
PARTS = {
    "[Content_Types].xml": TYPES,
    "_rels/.rels": ROOT,
    "template/main.xml": "<Template/>",
    "template/_rels/main.xml.rels": RELS,
    "tables/contacts.xml": "<Contacts/>",
}


class StreamingBuffer(io.BytesIO):
    def seek(self, *args):
        raise io.UnsupportedOperation("original non-seekable ZIP fixture")


def package(parts, compression, streaming=False):
    output = StreamingBuffer() if streaming else io.BytesIO()
    with zipfile.ZipFile(output, "w", compression=compression) as archive:
        for name, value in parts.items():
            archive.writestr(name, value)
    return output.getvalue()


def execute(cli, path, contents, options=(), success=True):
    path.write_bytes(contents)
    result = subprocess.run(
        [str(cli), "inspect", str(path), "--format", "tsv", *options],
        capture_output=True, check=False,
    )
    assert path.read_bytes() == contents
    if success:
        assert result.returncode == 0, result.stderr
        return list(csv.reader(io.StringIO(result.stdout.decode()), delimiter="\t"))
    assert result.returncode == 2, result.stderr
    assert result.stdout == b"", result.stdout
    # Control XML and filenames must not leak into failure diagnostics.
    assert b"main.xml" not in result.stderr
    return None


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--cli", type=Path, required=True)
    args = parser.parse_args()
    count = 0
    with tempfile.TemporaryDirectory(prefix="tablecraft-template-controls-") as directory:
        path = Path(directory) / "original.accdt"
        for compression in [zipfile.ZIP_STORED, zipfile.ZIP_DEFLATED]:
            data = package(PARTS, compression)
            for suffix in [".accdt", ".zip", ".bin"]:
                rows = execute(args.cli, path.with_suffix(suffix), data)
                assert ["Container", "Access template (OPC ZIP)"] in rows
                assert ["Content parts", "2"] in rows
                assert ["Template metadata", "template/main.xml"] in rows
                assert ["Table reading", "Bounded inline XSD data"] in rows
                assert ["tables/contacts.xml", "text/xml", "11", "0"] in rows
                count += 1
            streamed = package(PARTS, compression, streaming=True)
            assert ["Content parts", "2"] in execute(args.cli, path, streamed)
            count += 1
            assert execute(args.cli, path, data, options=("--catalog",)) == [["Name", "Kind", "Storage", "Part", "Stored data"]]
            count += 1
            for root in [
                ROOT.replace("template/start", "template/wrong"),
                ROOT.replace("template/main.xml", "missing.xml"),
                ROOT.replace("template/main.xml", "../../escape.xml"),
                ROOT.replace("Target=", 'TargetMode="External" Target='),
                '<!DOCTYPE x [<!ENTITY e SYSTEM "file:///private">]>' + ROOT,
                ROOT + ROOT,
            ]:
                parts = {**PARTS, "_rels/.rels": root}
                execute(args.cli, path, package(parts, compression), success=False)
                count += 1
            bad = bytearray(data)
            # Flip the first central CRC; the local/central consistency check fails.
            central = data.index(b"PK\x01\x02")
            bad[central + 16] ^= 1
            execute(args.cli, path, bad, success=False)
            count += 1
            for name in ["../escape.xml", "a%2fb.xml", "TABLES/contacts.xml"]:
                execute(
                    args.cli, path,
                    package({**PARTS, name: "<Bad/>"}, compression), success=False,
                )
                count += 1
    print(f"Passed {count} independent Python ZIP/OPC CLI controls; native Access unrun.")


if __name__ == "__main__":
    main()
